spec.expr:
sum(rate(
  http_requests_total{
    namespace="demo",
    pod=~"demo-api.*",
    handler!="/metrics"
  }[1m]
)) by (pod)

sum(rate(
  http_requests_total{
    namespace="demo",
    pod=~"backend-api.*",
    handler!="/metrics"
  }[1m]
)) by (pod)

histogram_quantile(
  0.50,
  sum by (le) (
    rate(
      http_request_duration_seconds_bucket{
        namespace="demo",
        pod=~"backend-api-.*",
        handler!="/metrics"
